// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount, uint256 extra) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, 1 ether);
        extra = bound(extra, 1, 1 ether);

        Reentrant r = new Reentrant(address(c), amount);
        vm.deal(address(r), amount + extra);
        vm.prank(address(r));
        c.deposit{value: amount}();

        // Top-level withdrawAll: reference sends Ether to r, whose receive() replays
        // withdrawAll.  In the reference the replay reverts (credit already zeroed and
        // balance check), but the outer call succeeds because only the inner replay fails.
        // In the mutant no Ether is ever sent, so no reply ever happens.
        vm.prank(address(r));
        bool ok; try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(ok, "outer withdrawAll should succeed");

        // Reference: r received exactly `amount` from the two calls, so its balance
        // must be exactly amount + extra (it started with amount + extra and copied
        // `amount` to c, then the replay did not move more out because it reverted).
        // Mutant: r received nothing back, so its balance is amount + extra - amount.
        assertEq(address(r).balance, amount + extra, "reentrant caller balance changed");
    }
}

contract Reentrant {
    address payable private owner;
    address private target;
    uint256 private amount;
    bool private entered;

    constructor(address _target, uint256 _amount) payable {
        owner = payable(msg.sender);
        target = _target;
        amount = _amount;
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            (bool ok, ) = target.call(abi.encodeWithSignature("withdrawAll()"));
            ok;
        }
    }
}
